import "./choose_us.css";
import React, { useEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

// choose images 
import choose1 from "../images/choose.png"
import choose2 from "../images/choose1.png"
import choose3 from "../images/choose3.png"

gsap.registerPlugin(ScrollTrigger);


function Choose() {

    

    const chooseRef = useRef(null);
    
        useEffect(() => {
            let ctx = gsap.context(() => {

                gsap.to(".bg-layer", {
                    scale: 1.3,
                    y: -50,
                    scrollTrigger: {
                        trigger: ".bg-layer",
                        start: "top bottom", // when the section enters viewport
                        end: "bottom top",   // when the section leaves viewport
                        scrub: 1,     
                    },
                });

                gsap.from(".choose1", {
                    scrollTrigger: {
                        trigger: ".choose1",
                        start: "top 80%",
                        end: "bottom 20%",
                        scrub:1,
                        toggleActions: "play none none reverse",
                    },
                    y: 100,
                    duration: 1,
                    ease: "power3.out",
                });
    
                gsap.from(".choose2", {
                    scrollTrigger: {
                        trigger: ".choose2",
                        start: "top 80%",
                        end: "bottom 20%",
                        scrub:1,
                        toggleActions: "play none none reverse",
                    },
                    x: 100,
                    duration: 1,
                    ease: "power3.out",
                });
    
                gsap.from(".choose3", {
                    scrollTrigger: {
                        trigger: ".choose3",
                        start: "top 30%",
                        end: "bottom 20%",
                        scrub:1,
                        toggleActions: "play none none reverse",
                    },
                    y: -100,
                    duration: 1,
                    ease: "power3.out",
                });
            }, chooseRef);
    
            return () => ctx.revert();
        }, []);

        
    

    return (
        <div className="container why_choose" ref={chooseRef}>
            <div className="bg-layer">
            </div>
            <div className="col-lg-8 " style={{ height: "100%" }}>
                <div className="row h-100">
                    <div className="col-lg-6 col-md-6 col-12 h-50 choose_us">
                        <div className="choose_boxes">
                            <div className="choose_top">
                                <span>1</span>
                                <h3 className="small_heading">Expert Local Guides</h3>
                            </div>
                            <div className="choose_bottom">
                                <p className="paragraphs">
                                    Explore Ladakh with guides who know every trail, pass, and hidden gem for an unforgettable journey.
                                </p>
                            </div>
                        </div>
                    </div>
                    <div className="col-lg-6 col-md-6 col-12 h-50 choose_us mt-md-0 mt-4">
                        <div className="choose_boxes">
                            <div className="choose_top">
                                <span>2</span>
                                <h3 className="small_heading">Thrilling Adventure Tours</h3>
                            </div>
                            <div className="choose_bottom">
                                <p className="paragraphs">
                                    Our carefully crafted tours take you through the most scenic and adventurous routes in Ladakh.
                                </p>
                            </div>
                        </div>
                    </div>
                    <div className="col-lg-6 col-md-6 col-12 h-50 choose_us mt-4">
                        <div className="choose_boxes">
                            <div className="choose_top">
                                <span>3</span>
                                <h3 className="small_heading">Complete Backup Support</h3>
                            </div>
                            <div className="choose_bottom">
                                <p className="paragraphs">
                                From emergency assistance to on-road support, we ensure your adventure is safe and worry-free.
                                </p>
                            </div>
                        </div>
                    </div>
                    <div className="col-lg-6 col-md-6 col-12 h-50 choose_us mt-4">
                        <div className="choose_boxes">
                            <div className="choose_top">
                                <span>4</span>
                                <h3 className="small_heading">Authentic Ladakh Experience</h3>
                            </div>
                            <div className="choose_bottom">
                                <p className="paragraphs">
                                Immerse yourself in the culture, landscapes, and experiences that only Ladakh <br /> can offer.
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <img className="choose1" src={choose1} alt="" />
            <img className="choose2" src={choose2} alt="" />
            <img className="choose3" src={choose3} alt="" />
        </div>
    )

}



export default Choose;