import { Button } from "./button";
import { Link } from "react-router-dom";
import React, { useEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

import "./winterTrek.css";

gsap.registerPlugin(ScrollTrigger);

function Winter() {
  const imageRef = useRef(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.to(imageRef.current, {
        scale: 1.4,
        y: -50,
        ease: "none",
        scrollTrigger: {
          trigger: imageRef.current,
          start: "top bottom",
          end: "bottom top",
          scrub: true, 
        },
      });
    });

    return () => ctx.revert();
  }, []);

  return (
    <div className="row winter_tour">
      <div className="col-lg-6 col-md-7 col-12 tour-text">
        <div className="section_heading_box3">
          <div className="heading_box">
            <h3>Frozen Trails</h3>
          </div>
        </div>
        <div className="text_section3">
          <h2 className="headings2">Winter Trekking</h2>
        </div>
        <p className="head_para3">
          Experience the iconic Chadar Trek in Ladakh a thrilling walk over the frozen Zanskar River amid snow-clad mountains and stunning Himalayan landscapes
        </p>
        <div className="row">
          <div className="col-6 winter-left">
            <p>Walk across the frozen <br /> Zanskar River.</p>
            <p>Explore remote Ladakhi <br /> villages.</p>
          </div>
          <div className="col-6 winter-right">
            <p>Camp in the heart of <br /> the wilderness.</p>
            <p>Enjoy breathtaking Himalayan <br /> views.</p>
          </div>
        </div>
        <Link to="/about"><Button className="winter_tour_btn" label="Book Now" /></Link>
      </div>
      <div className="col-lg-6 col-md-5 col-12 tour-image">
        <img
          ref={imageRef}
          src="https://www.treknomads.com/blog/wp-content/uploads/2022/11/shutterstock_715794370-min-scaled.jpg"
          alt="Winter Trek"
        />
      </div>
    </div>
  );
}

export default Winter;
