import React, { useState, useRef } from "react";
import "./Accordion.css";

const data = [
  {
    question: "What types of bikes are available for rent in Ladakh?",
    answer: `We offer a wide range of bikes including Royal Enfield Classic 350/500, Himalayan, Bullet, and Adventure bikes, along with scooters for short local rides. All bikes are well-maintained and regularly serviced for high-altitude conditions.`
  },
  {
    question: "What are the documents required to rent a bike in Ladakh?",
    answer: `You’ll need to provide a valid driving license, government-issued photo ID (like Aadhaar or Passport), and a security deposit. Foreign nationals must present their international driving permit (IDP).`
  },
  {
    question: "Can I rent a bike without a riding experience?",
    answer: `For safety reasons, we recommend that riders have at least basic biking experience before renting a motorcycle in Ladakh. The terrain can be challenging, with steep passes and rough roads. Beginners can opt for guided bike tours with our experienced crew.`
  },
  {
    question: "Is it safe to ride a bike in Ladakh?",
    answer: `Yes, it’s safe — provided you follow traffic rules and ride cautiously. Always wear a helmet, avoid night rides, and take regular breaks to stay hydrated and prevent altitude fatigue. Our team also provides a briefing session before every trip.`
  },
  {
    question: "Do you provide helmets and accessories with the bike?",
    answer: `Yes, every rental comes with two helmets (for rider and pillion). You can also rent riding jackets, gloves, knee guards, and luggage carriers for added comfort and safety.`
  },
  {
    question: "What happens if the bike breaks down during the trip?",
    answer: `We provide roadside assistance and backup support across major routes like Leh–Nubra–Pangong–Tso Moriri. In case of minor issues, our team will guide you on quick fixes. For major problems, a replacement bike will be arranged wherever possible.`
  }
];

export default function Bike_Accordion() {
  const [activeIndex, setActiveIndex] = useState(null);
  const answerRefs = useRef([]);

  const toggleAccordion = (index) => {
    setActiveIndex(index === activeIndex ? null : index);
  };

  return (
    <div className="faq_wrapper">
      {data.map((item, index) => (
        <div className="faq_container faq_services" key={index}>
          <div
            className={`question ${activeIndex === index ? "active" : ""}`}
            onClick={() => toggleAccordion(index)}
          >
            {item.question}
          </div>
          <div
            className="answer_wrapper"
            ref={(el) => (answerRefs.current[index] = el)}
            style={{
              maxHeight:
                activeIndex === index
                  ? `${answerRefs.current[index]?.scrollHeight}px`
                  : "0px"
            }}
          >
            <div className="answer">{item.answer}</div>
          </div>
        </div>
      ))}
    </div>
  );
}
