import { Link } from "react-router-dom";
import { useRef, useEffect, useState } from "react";
import { gsap } from "gsap";

import bars from "../images/icons/main-menu.png";
import close_bar from "../images/icons/close.png";
import address from "../images/icons/address.png";
import contact from "../images/icons/phone2.png";
import logo from "../images/logo.png";
import search from "../images/icons/search.png";
import facebook from "../images/icons/social/facebook.png";
import instagram from "../images/icons/social/instagram.png";
import { Button } from "./button";
import "./nav.css";

function Nav() {
  // Refs for elements
  const menuBarRef = useRef(null);
  const contentRef = useRef(null);
  const closeBtnRef = useRef(null);
  const smallContentRef = useRef(null);

  const [open, setOpen] = useState(false);

 useEffect(() => {
  const menuBar = menuBarRef.current;
  const offcanvas = menuBar.querySelector(".offcanvas_content");
  const content = contentRef.current;
  const closeBtn = closeBtnRef.current;
  const mobileLink = smallContentRef.current;

  const largeScreen = window.matchMedia("(min-width: 1201px)");
  const smallScreen = window.matchMedia("(max-width: 1200px)");

  let openMenu, closeMenu;

  if (largeScreen.matches) {
    // 💻 Animation for large screens
    openMenu = () => {
      if (!open) {
        gsap.to(menuBar.querySelector("img.bars"), { opacity: 0, duration: 0.2 });

        gsap.to(offcanvas, {
          duration: 0.6,
          width: "500px",
          height: "500px",
          borderRadius: "10px",
          ease: "elastic.out(1,1)",
          zIndex: 100,
        });

        gsap.to(content, {
          opacity: 1,
          display: "block",
          duration: 0.4,
          delay: 0.4,
        });

        gsap.to(closeBtn, {
          opacity: 1,
          pointerEvents: "auto",
          duration: 0.4,
          delay: 0.5,
        });

        setOpen(true);
      }
    };

    closeMenu = () => {
      gsap.to(content, {
        opacity: 0,
        duration: 0.3,
        onComplete: () => (content.style.display = "none"),
      });

      gsap.to(offcanvas, {
        duration: 0.5,
        width: "50%",
        height: "50%",
        borderRadius: "10px",
        ease: "power2.out",
        zIndex: -1,
      });

      gsap.to(closeBtn, {
        opacity: 0,
        pointerEvents: "none",
        duration: 0.3,
      });

      gsap.to(menuBar.querySelector("img.bars"), {
        opacity: 1,
        duration: 0.3,
        delay: 0.5,
      });

      setOpen(false);
    };
  } else if (smallScreen.matches) {
    // 📱 Animation for small screens
    openMenu = () => {
      if (!open) {

        gsap.to(menuBar.querySelector("img.bars"), { opacity: 0, duration: 0.2 });

        gsap.to(offcanvas, {
          duration: 0.4,
          height: "90%",
          width: "95%",
          opacity: 1,
          ease: "elastic.out(1,1)",
          zIndex: 100,
        });

        gsap.to(mobileLink, {
          opacity: 1,
          display: "block",
          duration: 0.3,
          delay: 0.2,
        });

        gsap.to(closeBtn, {
          opacity: 1,
          pointerEvents: "auto",
          duration: 0.4,
          delay: 0.5,
        });

        setOpen(true);
      }
    };



    closeMenu = () => {
      gsap.to(mobileLink, {
        opacity: 0,
        duration: 0.3,
        onComplete: () => (content.style.display = "none"),
      });

      gsap.to(offcanvas, {
        duration: 0.5,
        opacity: 0,
        width: "0%",
        height: "0%",
        borderRadius: "10px",
        ease: "power2.out",
        zIndex: -1,
      });

      gsap.to(closeBtn, {
        opacity: 0,
        pointerEvents: "none",
        duration: 0.3,
      });

      gsap.to(menuBar.querySelector("img.bars"), {
        opacity: 1,
        duration: 0.3,
        delay: 0.5,
      });

      setOpen(false);
    };
  }

  if (!openMenu || !closeMenu) return;

  // Attach event listeners
  menuBar.addEventListener("click", openMenu);
  closeBtn.addEventListener("click", closeMenu);

  // Cleanup
  return () => {
    menuBar.removeEventListener("click", openMenu);
    closeBtn.removeEventListener("click", closeMenu);
  };
}, [open]);





// below 1201px 



  return (
    <nav className="container-fluid">
      <div className="container nav_parent">
        <div className="col-12 nav_bar">
          <div className="row flex-column align-items-center">
            <div className="col-lg-12 col-md-12 col-sm-12 col-11 top_nav">
              <div className="d-flex align-items-center justify-content-between">
                <div className="top_nav_text">
                  <p className="paragraphs">Welcome To Travel To Himalaya</p>
                </div>
                <div className="social_media d-flex align-items-center">
                  <img src={facebook} alt="" />
                  <img src={instagram} alt="" />
                </div>
              </div>
            </div>

            <div className="col-12 main_nav">
              <div className="row">
                <div className="col-5 d-flex align-items-center offcanvas_parent">
                  {/* Menu Bar */}
                  <div ref={menuBarRef} className="bars_box menu-bar">
                    <img className="bars" src={bars} alt="menu icon" />
                    
                  <div className="offcanvas_content">
                    <div ref={contentRef} className="menu-content">
                        <h2 className="mainheading offcanvas_heading">Travel To Himalaya</h2>
                        <p className="paragraphs">Ladakh’s trusted travel partner for premium rides and unforgettable Himalayan adventures.</p>
                        <div className="contact_card_section contact_top_card_offcanvas">
                            <div className="contact_top_card  ">
                                <img src={address} alt="" />
                                <p className="paragraphs">Address</p>
                            </div>
                            <p className="paragraphs">Travel to himalaya <br /> Stalam Stalam Ladakh 194101</p>
                        </div>
                        <div className="contact_card_section  contact_top_card_offcanvas">
                            <div className="contact_top_card">
                                <img src={contact} alt="" />
                                <p className="paragraphs">Contact</p>
                            </div>
                            <p className="paragraphs">+91 987654321</p>
                            <p className="paragraphs">hello@traveltohimalaya.in</p>
                        </div>
                        <div className="contact_card_section  contact_top_card_offcanvas">
                            <div className="contact_top_card">
                                <p className="paragraphs">Follow Us</p>
                            </div>
                            <div className="social_media offcanvas_social d-flex align-items-center">
                                <img src={facebook} alt="" />
                                <img src={instagram} alt="" />
                            </div>
                        </div>
                    </div>

                    {/* small_content_menu */}

                    <div className="mobile_links" ref={smallContentRef}>
                        <ul className="nav_links_mobile left_nav_links">
                    <li className="mob_li">
                      <Link to="/" className="nav-link">
                        Home
                      </Link>
                    </li>
                    <li className="mob_li">
                      <Link to="/about" className="nav-link">
                        About
                      </Link>
                    </li>

                    <li className="mob_li hasDropdown">
                      <span>Services</span>
                      <ul className="dropdown">
                        <li>
                          <Link to="/bike" className="nav-link">
                            Bike Rental
                          </Link>
                        </li>
                        <li>Car Rental</li>
                        <li>Hotel Bookings</li>
                        <li>Custom Tours</li>
                      </ul>
                    </li>
                    <li className="mob_li hasDropdown">
                      <span>Packages</span>
                      <ul className="dropdown">
                        <li>Adventure Activities</li>
                        <li>Tour Packages</li>
                        <li>Winter Trekking</li>
                        <li>Trekking</li>
                      </ul>
                    </li>
                    <li className="mob_li">Gallery</li>
                    <li className="mob_li">FAQ's</li>

                  </ul>
                    </div>
                    
                  </div>
                </div>

                <img ref={closeBtnRef} className="close-btns close_canvas" src={close_bar} alt="menu icon" />
                
                  

                  {/* Navigation Links */}
                  <ul className="nav_links left_nav_links">
                    <li>
                      <Link to="/" className="nav-link">
                        Home
                      </Link>
                    </li>
                    <li>
                      <Link to="/about" className="nav-link">
                        About
                      </Link>
                    </li>

                    <li className="hasDropdown">
                      <span>Services</span>
                      <ul className="dropdown">
                        <li>
                          <Link to="/bike" className="nav-link">
                            Bike Rental
                          </Link>
                        </li>
                        <li>Car Rental</li>
                        <li>Hotel Bookings</li>
                        <li>Custom Tours</li>
                      </ul>
                    </li>
                  </ul>
                </div>

                <div className="col-2 d-flex justify-content-center">
                  <Link to="/">
                    <img className="nav_logo" src={logo} alt="logo" />
                  </Link>
                </div>

                <div className="col-5 d-flex align-items-center justify-content-end">
                  <ul className="nav_links">
                    <li className="hasDropdown">
                      <span>Packages</span>
                      <ul className="dropdown">
                        <li>Adventure Activities</li>
                        <li>Tour Packages</li>
                        <li>Winter Trekking</li>
                        <li>Trekking</li>
                      </ul>
                    </li>
                    <li>Gallery</li>
                    <li>FAQ's</li>
                  </ul>
                  <Link to="/contact">
                    <Button className="nav_button" label="Contact Us" />
                  </Link>
                  <form action="" className="nav_form nav_form_right">
                    <input
                      placeholder="Search"
                      type="text"
                      className="nav_search"
                    />
                    <button type="submit">
                      <img src={search} alt="" />
                    </button>
                  </form>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
}

export default Nav;
