import { Button, Button1 } from "../components/button";
// import React, { useEffect, useRef } from "react";

import "../components/contact.css";
import Footer from "../components/footer";

// icons 
import address from "../images/icons/address.png";
import contact from "../images/icons/phone2.png";


function Contact(){
    return (
        <>
        <div className="parent">
        <header className="hero_section_about">
                <div className="container">
                    <div className="col-lg-12">
                        <div className="row">
                            <div className="col-lg-6 hero_about_left">
                                <div className="text_section_about">
                                    
                                    <h1 className="mainheading about_hero_txt pb-2 mt-4">Say Hello .</h1>
                                    <p className="head_para_about">Driven by Passion, Fueled by Adventure, and Guided by the Spirit of Discovery.</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

            </header>


            {/* form section  */}

            <div className="container">
                <div className="row">
                    <div className="col-lg-8">
                <form action="" className="contact_form">
                    <div className="row">
                        <div className="col-lg-6">
                            <div className="form_container">
                                <label className="paragraphs" htmlFor="">Full Name</label><br />
                                <input type="text" />
                            </div>
                        </div>
                        <div className="col-lg-6">
                            <div className="form_container">
                                <label className="paragraphs" htmlFor="">Email Address</label><br />
                                <input type="text" />
                            </div>
                        </div>
                    </div>
                    <div className="row">
                        <div className="col-lg-6">
                            <div className="form_container form_under_container">
                                <label className="paragraphs" htmlFor="">Phone Number</label><br />
                                <input type="text" />
                            </div>
                        </div>
                        <div className="col-lg-6">
                            <div className="form_container form_under_container">
                                <label className="paragraphs" htmlFor="">Subject</label><br />
                                <select name="" id="">
                                    <option selected disabled value="">Select Any one</option>
                                    <option value="">Bike Rental</option>
                                    <option value="">Car Rental</option>
                                    <option value="">Hotel Booking</option>
                                    <option value="">Tour Information</option>
                                    <option value="">Other</option>
                                </select>
                            </div>
                        </div>
                        <div className="col-lg-12">
                            <div className="form_under_container">
                             <label htmlFor="">Message</label><br />
                             <textarea name="" id=""></textarea>
                            </div>

                        </div>
                        <div className="col-lg-12">
                            <div className="form_under_container_sbmit">
                                <input type="submit" />
                            </div>
                        </div>
                    </div>
                </form>
                </div>
                <div className="col-lg-4 contact_info_parent">
                    <div className="contact_info_card">
                        <h2 className="mainheading">Get In Touch</h2>

                        <div className="contact_card_section">
                            <div className="contact_top_card contact_info_card_sec">
                                <img src={address} alt="" />
                                <p className="paragraphs">Address</p>
                            </div>
                            <p className="paragraphs">Travel to himalaya <br /> Stalam Stalam Ladakh 194101</p>
                        </div>
                        <div className="contact_card_section contact_info_card_sec">
                            <div className="contact_top_card">
                                <img src={contact} alt="" />
                                <p className="paragraphs">Contact</p>
                            </div>
                            <p className="paragraphs">+91 987654321</p>
                            <p className="paragraphs">hello@traveltohimalaya.in</p>
                        </div>
                    </div>
                    
                </div>
                </div>
            </div>

            <div className="container-fluid map_embed section-p">
                <div className="view_map">
                    <div className="get_direction">
                        <a href="">
                        <div className="direction_icon">
                            <img src={address} alt="" />
                        </div>
                        </a>
                    </div>
                    <iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3568297.4724584036!2d73.67438050065738!3d32.23632362607907!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x38fdeb4f3606cfc1%3A0x21869de1afb06c32!2sHotel%20Hill%20Top%20Heaven!5e1!3m2!1sen!2sin!4v1761127354648!5m2!1sen!2sin"  allowfullscreen="" loading="lazy"></iframe>
                </div>
            </div>
            </div>



            {/* 2nd part */}
                        <div className="about_footer">
                            <Footer />
                        </div>
        </>
    )
}


export default Contact;